 }
 // windswept coastal trees and rocks around perimeter
 for(let i=0;i<28;i++){
  const angle=i/28*Math.PI*2,r=rand(31,38),x=Math.cos(angle)*r,z=Math.sin(angle)*r*.88;
  if(Math.abs(x)<24&&Math.abs(z)<24)continue;
