const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright');
(async()=>{
 const browser=await chromium.launch({headless:true,args:['--use-gl=swiftshader','--enable-webgl','--no-sandbox']});
 for (const viewport of [{width:390,height:844},{width:820,height:1180},{width:1180,height:820}]) {
  const page=await browser.newPage({viewport,hasTouch:true,isMobile:true});
  const errors=[];page.on('pageerror',e=>errors.push(e.message));
  await page.goto('http://localhost:3002/',{waitUntil:'networkidle'});
  await page.locator('#deploy-btn').click();await page.locator('#match-btn').click();
  await page.waitForTimeout(1400);
  const initial=await page.evaluate(()=>({controls:getComputedStyle(document.querySelector('#touch-controls')).display,stick:document.querySelector('#touch-stick').getBoundingClientRect().toJSON(),fire:document.querySelector('#touch-fire').getBoundingClientRect().toJSON(),ammo:document.querySelector('#ammo-now').textContent,canvas:document.querySelector('#game-canvas').getBoundingClientRect().toJSON(),overflow:document.documentElement.scrollWidth>innerWidth||document.documentElement.scrollHeight>innerHeight}));
  if(viewport.width===390){
   await page.evaluate(()=>{window.__canvasMoves=[];document.querySelector('#game-canvas').addEventListener('pointermove',e=>window.__canvasMoves.push([e.pointerId,e.clientX,e.clientY]));});
   const session=await page.context().newCDPSession(page);const stick=initial.stick,fire=initial.fire;
   const pts=[{x:stick.x+stick.width/2,y:stick.y+stick.height/2,id:1},{x:250,y:400,id:2},{x:fire.x+fire.width/2,y:fire.y+fire.height/2,id:3}];
   await session.send('Input.dispatchTouchEvent',{type:'touchStart',touchPoints:pts});
   await session.send('Input.dispatchTouchEvent',{type:'touchMove',touchPoints:[{...pts[0],x:pts[0].x+25},{...pts[1],x:pts[1].x+32,y:pts[1].y-15},pts[2]]});
   await page.waitForTimeout(250);
   const active=await page.evaluate(()=>({knob:getComputedStyle(document.querySelector('.stick-knob')).transform,ammo:document.querySelector('#ammo-now').textContent,moves:window.__canvasMoves,rect:document.querySelector('#touch-controls').getBoundingClientRect().toJSON()}));
   await session.send('Input.dispatchTouchEvent',{type:'touchEnd',touchPoints:[]});
   console.log(JSON.stringify({viewport,initial,active,errors}));
  } else console.log(JSON.stringify({viewport,initial,errors}));
  await page.close();
 }
 await browser.close();
})().catch(e=>{console.error(e);process.exit(1)});

